/* AUTO-GENERATED by scripts/build-tokens.ts from tokens/*.json. Do not edit by hand; run `bun run tokens`. */

:root {
  /* Primitive palette (do not use directly) */
  --palette-blue-50: #E6F0F5;
  --palette-blue-100: #CCE0EB;
  --palette-blue-200: #99C2D6;
  --palette-blue-300: #5E9DBC;
  --palette-blue-400: #2E7FA6;
  --palette-blue-500: #0A6E99;
  --palette-blue-600: #045275;
  --palette-blue-700: #03405C;
  --palette-blue-800: #022F44;
  --palette-blue-900: #01202E;
  --palette-slate-0: #FFFFFF;
  --palette-slate-50: #F3F7FA;
  --palette-slate-100: #E9EFF3;
  --palette-slate-200: #D5DEE5;
  --palette-slate-300: #B4C1CB;
  --palette-slate-400: #7A8995;
  --palette-slate-500: #6B7B87;
  --palette-slate-550: #627280;
  --palette-slate-600: #5B6B77;
  --palette-slate-700: #3D4F5C;
  --palette-slate-800: #26353F;
  --palette-slate-900: #0F1D26;
  --palette-teal-50: #E0F2F1;
  --palette-teal-200: #99D5CF;
  --palette-teal-600: #0F766E;
  --palette-teal-700: #115E59;
  --palette-green-100: #DCFCE7;
  --palette-green-200: #BBF7D0;
  --palette-green-500: #22C55E;
  --palette-green-800: #166534;
  --palette-amber-100: #FEF3C7;
  --palette-amber-200: #FDE68A;
  --palette-amber-500: #F59E0B;
  --palette-amber-800: #92400E;
  --palette-red-100: #FEE2E2;
  --palette-red-200: #FECACA;
  --palette-red-500: #EF4444;
  --palette-red-600: #DC2626;
  --palette-red-700: #B91C1C;
  --palette-red-800: #991B1B;
  --palette-sky-100: #E0F2FE;
  --palette-sky-200: #BAE6FD;
  --palette-sky-500: #0EA5E9;
  --palette-sky-800: #075985;
  --palette-chart-orange: #EB6834;
  --palette-chart-aqua: #1BAF7A;
  --palette-chart-yellow: #EDA100;
  --palette-chart-magenta: #E87BA4;
  --palette-chart-green: #008300;
  --palette-chart-violet: #6250D6;
  --palette-chart-red: #E34948;

  /* Semantic colors */
  --background: var(--palette-slate-0);
  --foreground: var(--palette-slate-900);
  --foreground-secondary: var(--palette-slate-700);
  --card: var(--palette-slate-0);
  --card-foreground: var(--palette-slate-900);
  --popover: var(--palette-slate-0);
  --popover-foreground: var(--palette-slate-900);
  --primary: var(--palette-blue-600);
  --primary-foreground: var(--palette-slate-0);
  --primary-hover: var(--palette-blue-700);
  --secondary: var(--palette-slate-50);
  --secondary-foreground: var(--palette-slate-900);
  --secondary-hover: var(--palette-slate-100);
  --muted: var(--palette-slate-50);
  --muted-foreground: var(--palette-slate-600);
  --foreground-subtle: var(--palette-slate-550);
  --field: var(--palette-slate-100);
  --field-hover: var(--palette-slate-200);
  --accent: var(--palette-blue-50);
  --accent-foreground: var(--palette-blue-600);
  --highlight: var(--palette-teal-600);
  --highlight-subtle: var(--palette-teal-50);
  --highlight-foreground: var(--palette-teal-700);
  --border: var(--palette-slate-200);
  --input: var(--palette-slate-400);
  --ring: var(--palette-blue-600);
  --destructive: var(--palette-red-600);
  --destructive-foreground: var(--palette-slate-0);
  --destructive-hover: var(--palette-red-700);
  --success: var(--palette-green-500);
  --success-subtle: var(--palette-green-100);
  --success-foreground: var(--palette-green-800);
  --success-border: var(--palette-green-200);
  --warning: var(--palette-amber-500);
  --warning-subtle: var(--palette-amber-100);
  --warning-foreground: var(--palette-amber-800);
  --warning-border: var(--palette-amber-200);
  --danger: var(--palette-red-500);
  --danger-subtle: var(--palette-red-100);
  --danger-foreground: var(--palette-red-800);
  --danger-border: var(--palette-red-200);
  --info: var(--palette-sky-500);
  --info-subtle: var(--palette-sky-100);
  --info-foreground: var(--palette-sky-800);
  --info-border: var(--palette-sky-200);
  --chart-1: var(--palette-blue-500);
  --chart-2: var(--palette-chart-orange);
  --chart-3: var(--palette-chart-aqua);
  --chart-4: var(--palette-chart-yellow);
  --chart-5: var(--palette-chart-magenta);
  --chart-6: var(--palette-chart-green);
  --chart-7: var(--palette-chart-violet);
  --chart-8: var(--palette-chart-red);
  --sidebar: var(--palette-slate-50);
  --sidebar-foreground: var(--palette-slate-900);
  --sidebar-primary: var(--palette-blue-600);
  --sidebar-primary-foreground: var(--palette-slate-0);
  --sidebar-accent: var(--palette-blue-50);
  --sidebar-accent-foreground: var(--palette-blue-600);
  --sidebar-border: var(--palette-slate-200);
  --sidebar-ring: var(--palette-blue-600);

  /* Fonts */
  --font-family-sans: "IBM Plex Sans", "IBM Plex Sans Thai", system-ui, sans-serif;
  --font-family-mono: "IBM Plex Mono", "IBM Plex Sans Thai", ui-monospace, monospace;

  /* Radius base (used by calc() inside some shadcn components) */
  --radius: 6px;

  /* Motion */
  --duration-fast: 120ms;
  --duration-base: 180ms;
}

:root,
[data-density="comfortable"] {
  --control-h: 44px;
  --control-h-sm: 36px;
  --control-h-lg: 48px;
  --row-h: 48px;
  --row-head-h: 44px;
  --icon-size: 18px;
  --table-font-size: 14px;
  --table-line-height: 20px;
  --page-gutter: 24px;
  --hit-min: 44px;
}

[data-density="compact"] {
  --control-h: 32px;
  --control-h-sm: 28px;
  --control-h-lg: 36px;
  --row-h: 36px;
  --row-head-h: 32px;
  --icon-size: 16px;
  --table-font-size: 13px;
  --table-line-height: 20px;
  --page-gutter: 16px;
  --hit-min: 0px;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-foreground-secondary: var(--foreground-secondary);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary-hover: var(--primary-hover);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary-hover: var(--secondary-hover);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-foreground-subtle: var(--foreground-subtle);
  --color-field: var(--field);
  --color-field-hover: var(--field-hover);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-highlight: var(--highlight);
  --color-highlight-subtle: var(--highlight-subtle);
  --color-highlight-foreground: var(--highlight-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-destructive-hover: var(--destructive-hover);
  --color-success: var(--success);
  --color-success-subtle: var(--success-subtle);
  --color-success-foreground: var(--success-foreground);
  --color-success-border: var(--success-border);
  --color-warning: var(--warning);
  --color-warning-subtle: var(--warning-subtle);
  --color-warning-foreground: var(--warning-foreground);
  --color-warning-border: var(--warning-border);
  --color-danger: var(--danger);
  --color-danger-subtle: var(--danger-subtle);
  --color-danger-foreground: var(--danger-foreground);
  --color-danger-border: var(--danger-border);
  --color-info: var(--info);
  --color-info-subtle: var(--info-subtle);
  --color-info-foreground: var(--info-foreground);
  --color-info-border: var(--info-border);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-chart-6: var(--chart-6);
  --color-chart-7: var(--chart-7);
  --color-chart-8: var(--chart-8);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  --font-sans: var(--font-family-sans);
  --font-mono: var(--font-family-mono);
  --font-heading: var(--font-sans);

  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 6px;
  --radius-xl: 8px;
  --radius-2xl: 12px;
  --radius-4xl: 9999px;
  --radius-3xl: 12px;

  --spacing-control: var(--control-h);
  --spacing-control-sm: var(--control-h-sm);
  --spacing-control-lg: var(--control-h-lg);
  --spacing-row: var(--row-h);
  --spacing-row-head: var(--row-head-h);
  --spacing-icon: var(--icon-size);
  --spacing-gutter: var(--page-gutter);
  --spacing-hit: var(--hit-min);
}

@theme {
  --shadow-xs: 0 1px 2px rgb(15 29 38 / 0.05);
  --shadow-sm: 0 1px 3px rgb(15 29 38 / 0.08), 0 1px 2px rgb(15 29 38 / 0.04);
  --shadow-md: 0 4px 12px rgb(15 29 38 / 0.08), 0 1px 3px rgb(15 29 38 / 0.06);
  --shadow-lg: 0 12px 32px rgb(15 29 38 / 0.12), 0 2px 6px rgb(15 29 38 / 0.06);
}

/* Dashboard numbers only */
@utility type-display {
  font-size: 30px;
  line-height: 38px;
  font-weight: 600;
  letter-spacing: -0.01em;
}

/* Page title */
@utility type-h1 {
  font-size: 24px;
  line-height: 32px;
  font-weight: 600;
}

/* Section title */
@utility type-h2 {
  font-size: 20px;
  line-height: 28px;
  font-weight: 600;
}

/* Card or dialog title */
@utility type-h3 {
  font-size: 18px;
  line-height: 26px;
  font-weight: 600;
}

/* Group title */
@utility type-h4 {
  font-size: 16px;
  line-height: 24px;
  font-weight: 600;
}

/* Long-form reading */
@utility type-body-lg {
  font-size: 16px;
  line-height: 24px;
  font-weight: 400;
}

/* Default UI text */
@utility type-body {
  font-size: 14px;
  line-height: 22px;
  font-weight: 400;
}

/* Emphasis, labels */
@utility type-body-strong {
  font-size: 14px;
  line-height: 22px;
  font-weight: 500;
}

/* Table cells: 14/20 comfortable, 13/20 compact */
@utility type-table {
  font-size: var(--table-font-size);
  line-height: var(--table-line-height);
  font-weight: 400;
}

/* Meta info, timestamps, counters */
@utility type-caption {
  font-size: 12px;
  line-height: 18px;
  font-weight: 400;
}

/* IDs and codes */
@utility type-code {
  font-family: var(--font-mono);
  font-size: 13px;
  line-height: 20px;
  font-weight: 400;
}

/*
 * Self-hosted fonts (Fontsource). Each file declares unicode-range subsets,
 * so the browser downloads only the scripts a page actually uses.
 * Weights: 400 regular, 500 medium, 600 semibold. Do not add 700: Thai
 * glyphs close up at small sizes when bold.
 */
@import "@fontsource/ibm-plex-sans/400.css";
@import "@fontsource/ibm-plex-sans/500.css";
@import "@fontsource/ibm-plex-sans/600.css";
@import "@fontsource/ibm-plex-sans-thai/400.css";
@import "@fontsource/ibm-plex-sans-thai/500.css";
@import "@fontsource/ibm-plex-sans-thai/600.css";
@import "@fontsource/ibm-plex-mono/400.css";
@import "@fontsource/ibm-plex-mono/500.css";

/* MOOVE base styles. Shipped with the moove-theme registry item. */

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    @apply font-sans;
    -webkit-text-size-adjust: 100%;
    text-rendering: optimizeLegibility;
  }
  body {
    @apply bg-background type-body text-foreground antialiased;
  }
  code,
  kbd,
  samp {
    @apply font-mono;
  }
  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      transition-duration: 0.01ms !important;
    }
  }
}

/*
 * Focus: a solid 2px ring with a 2px white offset on every action, visible on
 * white, Secondary and Accent surfaces. Unlayered so it beats `outline-none`.
 * Field controls keep their own border + ring treatment.
 */
:is(
    button,
    a[href],
    [role="button"],
    [role="tab"],
    [role="checkbox"],
    [role="radio"],
    [role="switch"],
    [role="menuitem"],
    [role="option"],
    summary
  ):focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
  --tw-ring-shadow: 0 0 #0000;
}

/*
 * Touch target: in comfortable density, controls shorter than 44px get an
 * invisible hit area of at least --hit-min (44px). Compact sets it to 0.
 */
[data-slot="button"][data-size="sm"],
[data-slot="button"][data-size="xs"],
[data-slot="button"][data-size="icon-sm"],
[data-slot="button"][data-size="icon-xs"] {
  position: relative;
}
[data-slot="button"][data-size="sm"]::after,
[data-slot="button"][data-size="xs"]::after,
[data-slot="button"][data-size="icon-sm"]::after,
[data-slot="button"][data-size="icon-xs"]::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: max(100%, var(--hit-min));
  height: max(100%, var(--hit-min));
  transform: translate(-50%, -50%);
}

/*
 * Chart color themes. Set once per app (or section) with <html data-chart-theme="violet">; every chart
 * below it follows. The default theme lives in tokens.css (--chart-1 … --chart-8, blue first).
 *
 * Each order below keeps the 8 validated hues and only changes their order, which is what makes a
 * palette color-blind safe. Validated with validate_palette.js (light, surface #FFFFFF, adjacent pairs):
 *
 *   default  blue   → worst adjacent CVD ΔE 9.1, normal-vision ΔE 19.6
 *   violet   violet → worst adjacent CVD ΔE 9.2, normal-vision ΔE 20.8
 *   orange   orange → worst adjacent CVD ΔE 9.2, normal-vision ΔE 15.0 (exactly at the 15 floor)
 *
 * Do not edit hues or reorder by eye. To add a theme, run the validator on the candidate order first.
 * Red and green are never slot 1: they are reserved for danger / success status.
 * Light mode only; dark-mode orders need their own validation against the dark surface.
 */
[data-chart-theme="violet"] {
  --chart-1: var(--palette-chart-violet);
  --chart-2: var(--palette-chart-magenta);
  --chart-3: var(--palette-chart-green);
  --chart-4: var(--palette-chart-yellow);
  --chart-5: var(--palette-chart-red);
  --chart-6: var(--palette-blue-500);
  --chart-7: var(--palette-chart-aqua);
  --chart-8: var(--palette-chart-orange);
}

[data-chart-theme="orange"] {
  --chart-1: var(--palette-chart-orange);
  --chart-2: var(--palette-chart-aqua);
  --chart-3: var(--palette-chart-green);
  --chart-4: var(--palette-chart-yellow);
  --chart-5: var(--palette-chart-magenta);
  --chart-6: var(--palette-blue-500);
  --chart-7: var(--palette-chart-violet);
  --chart-8: var(--palette-chart-red);
}
